+			String clientId = clientInfo.getId();
+			if (clientId != null && clientId.compareTo("") != 0) {
+				return clientId;
+			}
+			throw new Exception("Username null or empty");
+		} catch (Exception e) {
+			logger.error("Unable to retrieve user.");
+			throw new Exception("Unable to retrieve user.", e);
+		}
