+			URL redirectURL = getURL(connection.getHeaderField("Location"));
+				
+			logger.trace("{} is going to be redirect to {}", url.toString(), redirectURL.toString());
+			
+			connection = getConnection(redirectURL, method, inputStream, contentType);
+		}
+		
+		return connection;
+	}
