+				}
+				return compareResult;
+			}
+		};
+		SortedSet<NumberedFilter> ret = new TreeSet<>(comparator);
+		
+		ViewResult viewResult;
+		try {
+			// execute query in a specify bucket
+			viewResult = bucket.query(query);
