+		int count = spaceTimeSeries.size();
+		Filter firstRemovalKey = null;
+		for (Filter nf : spaceTimeSeries.keySet()) {
+			if (--count >= 0) {
+				padMapStorage(spaceTimeSeries.get(nf), temporalConstraint);
+			} else {
+				if (firstRemovalKey == null) {
+					firstRemovalKey = nf;
+				} else {
+					break;
+				}
+			}
+		}
+		if (firstRemovalKey != null) {
